import type { Frontmatter } from './frontmatter';

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  contentHtml: string;
  sourcePath: string;
  outputPath: string;
  template?: string;
  layout?: string;
  data: Frontmatter;
}

export interface BuildOptions {
  content: string;
  output: string;
  templates?: string;
}

import matter from 'gray-matter';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[] | string;
  template?: string;
  layout?: string;
  [key: string]: unknown;
}

const FRONTMATTER_RE = /^\uFEFF?---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(\r?\n|$)/;

export interface ParsedMarkdown {
  data: Frontmatter;
  body: string;
}

function normalizeDate(value: unknown): string | undefined {
  if (value == null) {
    return undefined;
  }
  if (value instanceof Date) {
    return value.toISOString().slice(0, 10);
  }
  return String(value);
}

/**
 * Strips the leading YAML frontmatter block (delimited by `---`) using a
 * regex, then parses the YAML with gray-matter. Stripping manually before
 * handing the body to `marked` is required: otherwise `marked` renders the
 * `---` delimiter block as literal HTML text.
 */
export function parseFrontmatter(raw: string): ParsedMarkdown {
  const match = FRONTMATTER_RE.exec(raw);
  if (!match) {
    return { data: {}, body: raw };
  }

  const yaml = match[1];
  const body = raw.slice(match[0].length);

  const parsed = matter(`---\n${yaml}\n---\n`);
  const source = parsed.data ?? {};

  const data: Frontmatter = {};
  for (const [key, value] of Object.entries(source)) {
    if (key === 'date') {
      data.date = normalizeDate(value);
    } else if (key === 'title' && typeof value === 'string') {
      data.title = value;
    } else if (key === 'tags') {
      data.tags = value as Frontmatter['tags'];
    } else if (key === 'template' && typeof value === 'string') {
      data.template = value;
    } else if (key === 'layout' && typeof value === 'string') {
      data.layout = value;
    } else {
      data[key] = value;
    }
  }

  return { data, body };
}

export function normalizeTags(tags: Frontmatter['tags']): string[] {
  if (tags == null) {
    return [];
  }
  if (Array.isArray(tags)) {
    return tags.map((t) => String(t).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

import Handlebars from 'handlebars';
import { promises as fs } from 'fs';
import type { Dirent } from 'fs';
import path from 'path';

export type TemplateContext = Record<string, unknown>;

const EXTENSIONS = ['.hbs', '.handlebars', '.html'];
const PARTIAL_EXTENSIONS = ['.hbs', '.handlebars'];

const DEFAULT_PAGE_TEMPLATE = `  <article>
    <h1>{{title}}</h1>
    {{#if meta}}<p class="meta">{{{meta}}}</p>{{/if}}
    {{{contentHtml}}}
  </article>
`;

const DEFAULT_LAYOUT = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{title}}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 48rem; margin: 0 auto; padding: 2rem 1rem; line-height: 1.6; }
    a { color: #2563eb; }
    .tags span { background: #e5e7eb; border-radius: 9999px; padding: 0.15rem 0.6rem; font-size: 0.8rem; margin-right: 0.35rem; }
    .meta { color: #6b7280; font-size: 0.9rem; }
  </style>
</head>
<body>
  <p><a href="index.html">&larr; All pages</a></p>
{{{body}}}
</body>
</html>
`;

function stripExtension(name: string): string {
  for (const ext of EXTENSIONS) {
    if (name.endsWith(ext)) {
      return name.slice(0, -ext.length);
    }
  }
  return name;
}

async function readEntries(dir: string): Promise<Dirent[]> {
  try {
    return await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return [];
  }
}

export class TemplateEngine {
  private readonly root: string;
  private readonly hbs: typeof Handlebars;
  private readonly pageTemplates = new Map<string, Handlebars.TemplateDelegate>();
  private readonly layouts = new Map<string, Handlebars.TemplateDelegate>();
  private readonly defaultPageTemplate: Handlebars.TemplateDelegate;
  private readonly defaultLayout: Handlebars.TemplateDelegate;

  constructor(root: string) {
    this.root = path.resolve(root);
    this.hbs = Handlebars.create();
    this.defaultPageTemplate = this.hbs.compile(DEFAULT_PAGE_TEMPLATE);
    this.defaultLayout = this.hbs.compile(DEFAULT_LAYOUT);
  }

  async load(): Promise<void> {
    await this.loadPartials();
    await this.loadLayouts();
    await this.loadPageTemplates();
  }

  private async loadPartials(): Promise<void> {
    const dir = path.join(this.root, 'partials');
    for (const entry of await readEntries(dir)) {
      if (!entry.isFile()) {
        continue;
      }
      const ext = path.extname(entry.name);
      if (!PARTIAL_EXTENSIONS.includes(ext)) {
        continue;
      }
      const name = entry.name.slice(0, -ext.length);
      const source = await fs.readFile(path.join(dir, entry.name), 'utf8');
      this.hbs.registerPartial(name, this.hbs.compile(source));
    }
  }

  private async loadLayouts(): Promise<void> {
    const dir = path.join(this.root, 'layouts');
    for (const entry of await readEntries(dir)) {
      if (!entry.isFile()) {
        continue;
      }
      const ext = path.extname(entry.name);
      if (!EXTENSIONS.includes(ext)) {
        continue;
      }
      const name = entry.name.slice(0, -ext.length);
      const source = await fs.readFile(path.join(dir, entry.name), 'utf8');
      this.layouts.set(name, this.hbs.compile(source));
    }
  }

  private async loadPageTemplates(): Promise<void> {
    for (const entry of await readEntries(this.root)) {
      if (!entry.isFile()) {
        continue;
      }
      const ext = path.extname(entry.name);
      if (!EXTENSIONS.includes(ext)) {
        continue;
      }
      const name = entry.name.slice(0, -ext.length);
      const source = await fs.readFile(path.join(this.root, entry.name), 'utf8');
      this.pageTemplates.set(name, this.hbs.compile(source));
    }
  }

  render(name: string, context: TemplateContext): string {
    const template = this.pageTemplates.get(stripExtension(name));
    if (template) {
      return template(context);
    }
    return this.defaultPageTemplate(context);
  }

  renderLayout(name: string, context: TemplateContext): string {
    const layout = this.layouts.get(stripExtension(name));
    if (layout) {
      return layout(context);
    }
    return this.defaultLayout(context);
  }
}

import type { Page } from './types';
import { TemplateEngine } from './templates';

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildMeta(page: Page): string {
  const metaParts: string[] = [];
  if (page.date) {
    metaParts.push(escapeHtml(page.date));
  }
  if (page.tags.length > 0) {
    metaParts.push(
      `<span class="tags">${page.tags
        .map((t) => `<span>${escapeHtml(t)}</span>`)
        .join('')}</span>`
    );
  }
  return metaParts.join(' · ');
}

function pageContext(page: Page): Record<string, unknown> {
  return {
    ...(page.data ?? {}),
    title: page.title,
    date: page.date,
    tags: page.tags,
    slug: page.slug,
    contentHtml: page.contentHtml,
    content: page.contentHtml,
    meta: buildMeta(page),
  };
}

export function renderPage(page: Page, engine: TemplateEngine): string {
  const context = pageContext(page);
  const body = engine.render(page.template ?? 'default', context);
  return engine.renderLayout(page.layout ?? 'default', { ...context, body });
}

export function renderIndex(pages: Page[], engine: TemplateEngine): string {
  const sorted = [...pages].sort((a, b) => a.title.localeCompare(b.title));

  const items = sorted
    .map((page) => {
      const metaParts: string[] = [];
      if (page.date) {
        metaParts.push(escapeHtml(page.date));
      }
      if (page.tags.length > 0) {
        metaParts.push(escapeHtml(page.tags.join(', ')));
      }
      const link = `${page.slug}.html`;
      return `    <li>
      <a href="${escapeHtml(link)}">${escapeHtml(page.title)}</a>
      ${metaParts.length > 0 ? `<span class="meta">(${metaParts.join(' · ')})</span>` : ''}
    </li>`;
    })
    .join('\n');

  const body = `
  <h1>All pages</h1>
  <ul>
${items}
  </ul>
`;

  return engine.renderLayout('default', { title: 'All pages', body });
}

import { promises as fs } from 'fs';
import path from 'path';
import { parseFrontmatter, normalizeTags } from './frontmatter';
import { markdownToHtml } from './markdown';
import { renderIndex, renderPage } from './render';
import { TemplateEngine } from './templates';
import type { BuildOptions, Page } from './types';

const MARKDOWN_EXT = /\.(md|markdown)$/i;

async function findMarkdownFiles(dir: string): Promise<string[]> {
  const results: string[] = [];
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await findMarkdownFiles(full)));
    } else if (entry.isFile() && MARKDOWN_EXT.test(entry.name)) {
      results.push(full);
    }
  }
  return results;
}

function slugFor(contentDir: string, filePath: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExt = relative.replace(MARKDOWN_EXT, '');
  return withoutExt.split(path.sep).join('/');
}

function titleFor(slug: string, data: { title?: string }): string {
  if (data.title && data.title.trim()) {
    return data.title.trim();
  }
  const segments = slug.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? slug;
}

export async function build(options: BuildOptions): Promise<Page[]> {
  const contentDir = path.resolve(options.content);
  const outputDir = path.resolve(options.output);
  const templatesDir = options.templates ?? './templates';

  const engine = new TemplateEngine(templatesDir);
  await engine.load();

  const files = (await findMarkdownFiles(contentDir)).sort();

  const pages: Page[] = [];
  for (const file of files) {
    const raw = await fs.readFile(file, 'utf8');
    const { data, body } = parseFrontmatter(raw);
    const contentHtml = markdownToHtml(body);
    const slug = slugFor(contentDir, file);

    pages.push({
      slug,
      title: titleFor(slug, data),
      date: data.date,
      tags: normalizeTags(data.tags),
      contentHtml,
      sourcePath: file,
      outputPath: path.join(outputDir, `${slug}.html`),
      template: data.template,
      layout: data.layout,
      data,
    });
  }

  await fs.mkdir(outputDir, { recursive: true });

  for (const page of pages) {
    await fs.mkdir(path.dirname(page.outputPath), { recursive: true });
    await fs.writeFile(page.outputPath, renderPage(page, engine), 'utf8');
  }

  await fs.writeFile(path.join(outputDir, 'index.html'), renderIndex(pages, engine), 'utf8');

  return pages;
}

export { build } from './build';
export { parseFrontmatter, normalizeTags } from './frontmatter';
export { markdownToHtml } from './markdown';
export { renderIndex, renderPage } from './render';
export { TemplateEngine } from './templates';
export type { TemplateContext } from './templates';
export type { Frontmatter, ParsedMarkdown } from './frontmatter';
export type { BuildOptions, Page } from './types';

